import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def find_rects(g):
    from collections import Counter
    c=Counter(x for row in g for x in row)
    res={}
    for col,n in c.items():
        if n<8 or col==0: continue
        cells=[(i,j) for i,row in enumerate(g) for j,x in enumerate(row) if x==col]
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        if len(set(rs))<3 or len(set(cs))<3: continue
        # check full rectangle border
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        ok=all((g[i][j]==col) for i in range(r0,r1+1) for j in range(c0,c1+1) if i in(r0,r1) or j in(c0,c1))
        if ok: res[col]=(r0,r1,c0,c1)
    return res

for k in ['Demo pair 1 input','Test input']:
    g=G[k]
    rects=find_rects(g)
    print(k, rects)
    rectcols=set(rects)
    dots={}
    for col in set(x for row in g for x in row):
        if col and col not in rectcols:
            dots[col]=sum(row.count(col) for row in g)
    print(' dots:', dots)
    for col,(r0,r1,c0,c1) in rects.items():
        H=r1-r0-1; W=c1-c0-1
        n=sum(1 for i in range(H) for j in range(W) if (i+j)%2==0)
        print(' rect',col,'interior',H,'x',W,'cb-count',n)
# check demo output pattern
go=G['Demo pair 1 output']; gi=G['Demo pair 1 input']
for col,(r0,r1,c0,c1) in find_rects(gi).items():
    cells=[(i,j) for i in range(r0+1,r1) for j in range(c0+1,c1) if go[i][j]!=0]
    print(col, 'out cells parity:', set((i-r0-1+j-c0-1)%2 for i,j in cells), len(cells))

