    dots={c:cnt[c] for c in cnt if c and c not in rectcols}
    out=[[0]*W for _ in range(H)]
    for col,(r0,r1,c0,c1) in rects.items():
        for i in range(r0,r1+1):
            for j in range(c0,c1+1):
